    if kind == 2:
        return ["torus2d", rng.randint(3, 6), rng.choice(['host', 'row'])]
    if kind == 3:
        return ["torus3d", rng.randint(3, 4), rng.choice(['host', 'line'])]
    if kind == 4:
        for _ in range(60):
            a = rng.randint(1, 6); h = rng.randint(1, 6); g = a * h + 1
