                return ["dragonfly", g, a, h, rng.choice(['router', 'group', 'target'])]
        return ["dragonfly", 3, 2, 1, 'group']
    for _ in range(60):
        l = rng.randint(1, 4); s = rng.randint(1, 4); g = rng.randint(2, 5)
        dense = rng.choice([0, 1])
        h = rng.randint(1, 4)
        if dense or (g - 1) == s * h:
            if g * (l + s) <= 60:
                return ["dragonfly-plus", g, l, s, h, dense, rng.choice(['tor', 'group'])]
    return ["dragonfly-plus", 2, 1, 1, 1, 1, 'group']


def make_session(rng):
    topology = pick_topology(rng)
    N, templates, domains = ref.build_topology(topology)
    G = rng.randint(1, 6)
    dom_of_tpl = domains
    # group templates by domain
    by_dom = {}
    for i, d in enumerate(domains):
        by_dom.setdefault(d, []).append(i)
    doms = sorted(by_dom)
    tasks = []
    for gid in range(G):
        if rng.random() < 0.15:
            continue  # empty group
        cls = rng.randrange(0, 4)
        d = rng.choice(doms)
        n = rng.randint(1, 4)
        for _ in range(n):
            tm = rng.choice(by_dom[d])
            tasks.append([tm, gid, rng.randint(1, 20), cls, 1 if rng.random() < 0.3 else 0])
    # dedupe task count cap
    tasks = tasks[:20]
    loads = [0] * G
    for t in tasks:
        loads[t[1]] += t[2]
    groups = []
    for gid in range(G):
        if loads[gid] == 0:
            groups.append([rng.randint(0, 3), rng.randint(1, 100)])
        else:
            budget = rng.choice([1, 2, 5, 10, 100, 10 ** 12])
            need = -(-loads[gid] // budget)
            while need > 64:
                budget = max(budget * 2, -(-loads[gid] // 64))
                need = -(-loads[gid] // budget)
            quota = max(1, need + rng.randint(0, 2)) if rng.random() < 0.7 else max(1, need)
            if quota > 64:
                quota = 64
                budget = max(budget, -(-loads[gid] // 64))
            groups.append([quota, budget])
    # usages
    use = [0] * N
    member = [[] for _ in range(G)]
    for t in tasks:
        member[t[1]].append(t)
    for gid in range(G):
        if not member[gid]:
            continue
        fp = set()
        for t in member[gid]:
            fp.update(templates[t[0]])
        for node in fp:
            use[node] += groups[gid][0]
    caps = [use[i] + rng.randint(0, 3) for i in range(N)]
    sess = {"topology": topology, "caps": caps, "groups": groups, "tasks": tasks,
            "query": make_query(rng, G, N, len(tasks)), "transactions": []}
    return sess, N, G, len(tasks), templates, domains


def make_query(rng, G, N, D):
    return {"groups": [rng.randrange(G) for _ in range(rng.randint(0, 4))],
            "nodes": [rng.randrange(N) for _ in range(rng.randint(0, 4))],
            "tasks": [rng.randrange(D) if D else 0 for _ in range(rng.randint(0, 4))]}


def make_transactions(rng, G, N, D, templates, domains, count):
    txs = []
    for _ in range(count):
        edits = []
        for _ in range(rng.randint(0, 6)):
            kind = rng.randrange(8)
            if kind == 0 and G > 1:
                edits.append(["move", rng.randrange(D) if D else 0, rng.randrange(G)])
            elif kind == 1:
                edits.append(["weight", rng.randrange(D) if D else 0, rng.randint(1, 30)])
            elif kind == 2:
                edits.append(["class", rng.randrange(D) if D else 0, rng.randrange(4)])
            elif kind == 3:
                edits.append(["bind", rng.randrange(D) if D else 0, rng.randrange(len(templates))])
            elif kind == 4:
                edits.append(["pin", rng.randrange(D) if D else 0, rng.choice([0, 1])])
            elif kind == 5:
                edits.append(["quota", rng.randrange(G), rng.randint(0, 8)])
            elif kind == 6:
                edits.append(["budget", rng.randrange(G), rng.randint(1, 100)])
            else:
                edits.append(["cap", rng.randrange(N), rng.randint(0, 12)])
        rev = rng.choice(['cur', 'cur', 'cur', 'stale'])
        tx = {"revision": '@', "edits": edits, "query": make_query(rng, G, N, D)}
        txs.append(tx)
    return txs


def annotate(session_spec, txs):
    rev = 0
    for tx in txs:
        if tx['revision'] == '@':
            tx['revision'] = rev
        # determine acceptance using the reference to advance revision
        tx['revision'] = tx['revision'] if tx['revision'] != 'stale' else rev + rng.randint(1, 3)
        res = None
        # need to simulate: run a single-transaction reference
        yield tx
        # after the tx, revision advances if accepted: handled by caller


def run_case(seed):
    rng = random.Random(seed)
    nsess = rng.randint(1, 2)
    sessions = []
    metas = []
    for _ in range(nsess):
        sess, N, G, D, templates, domains = make_session(rng)
        txs = make_transactions(rng, G, N, D, templates, domains, rng.randint(1, 6))
        sessions.append((sess, txs))
        metas.append((N, G, D, templates, domains))
    # fill revisions by simulating with the reference
    for sess, txs in sessions:
        s = ref.Session(dict(sess))
        if not s.legal():
            sess['transactions'] = []
            continue
        for tx in txs:
            if tx['revision'] == '@':
                tx['revision'] = s.revision
            else:
                tx['revision'] = s.revision + rng.randint(1, 3)
            out = s.transact(dict(tx))
            tx['revision'] = tx['revision'] if out['accepted'] else tx['revision']
    request = {"version": 2, "sessions": [s for s, _ in sessions]}
    for sess, txs in sessions:
        sess['transactions'] = [{k: tx[k] for k in ('revision', 'edits', 'query')} for tx in txs]
    expected = ref.run(request)
    raw = json.dumps(request, separators=(',', ':')).encode()
    p = harness.run(CAND, raw)
    if p.returncode != 0:
        return f'seed {seed}: engine rc={p.returncode} {p.stderr.decode()[:500]}'
    try:
        got = harness.strict_load(p.stdout)
    except Exception as e:
        return f'seed {seed}: bad json {e} {p.stdout[:300]}'
    if not harness.same(got, expected):
        return (f'seed {seed}: MISMATCH\n req={json.dumps(request)[:1200]}\n'
                f' got={json.dumps(got, default=str)[:1500]}\n exp={json.dumps(expected, default=str)[:1500]}')
    return None


if __name__ == '__main__':
    start = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 50
    bad = 0
    for seed in range(start, start + count):
        msg = run_case(seed)
        if msg:
            print(msg); bad += 1
            if bad > 3: break
    print('done', count, 'failures', bad)
